from tensorflow.keras.optimizers import Adam

learning_rates = [0.001, 0.01]
lr_results = []

for lr in learning_rates:

    model = Sequential([
        Input(shape=(X_train.shape[1],)),
        Dense(16, activation="relu"),
        Dense(1, activation="sigmoid")
    ])

    model.compile(
        optimizer=Adam(learning_rate=lr),
        loss="binary_crossentropy",
        metrics=["accuracy"]
    )

    history = model.fit(
        X_train,
        y_train,
        validation_split=0.2,
        epochs=20,
        batch_size=32,
        callbacks=[early_stop],
        verbose=1
    )

    lr_results.append({
        "Learning Rate": lr,
        "Best Training Accuracy": max(history.history["accuracy"]),
        "Best Validation Accuracy": max(history.history["val_accuracy"]),
        "Best Validation Loss": min(history.history["val_loss"])
    })

lr_results = pd.DataFrame(lr_results)

lr_results

lr_results.plot(
    x="Learning Rate",
    y="Best Validation Accuracy",
    kind="bar",
    figsize=(8, 5),
    legend=False
)

