import skfuzzy as fuzz
from skfuzzy import control as ctrl

import numpy as np
import skfuzzy as fuzz
from skfuzzy import control as ctrl

# Inputs
churn_risk = ctrl.Antecedent(
    np.arange(0, 101, 1), "churn_risk"
)

customer_value = ctrl.Antecedent(
    np.arange(0, 101, 1), "customer_value"
)

tenure = ctrl.Antecedent(
    np.arange(0, 101, 1), "tenure"
)

# Output
retention_priority = ctrl.Consequent(
    np.arange(0, 101, 1), "retention_priority"
)

# Churn Risk
churn_risk["low"] = fuzz.trimf(
    churn_risk.universe, [0, 0, 40]
)

churn_risk["medium"] = fuzz.trimf(
    churn_risk.universe, [25, 50, 75]
)

churn_risk["high"] = fuzz.trimf(
    churn_risk.universe, [60, 100, 100]
)


# Customer Value
customer_value["low"] = fuzz.trimf(
    customer_value.universe, [0, 0, 40]
)

customer_value["medium"] = fuzz.trimf(
    customer_value.universe, [25, 50, 75]
)

customer_value["high"] = fuzz.trimf(
    customer_value.universe, [60, 100, 100]
)


# Tenure
tenure["short"] = fuzz.trimf(
    tenure.universe, [0, 0, 40]
)

tenure["medium"] = fuzz.trimf(
    tenure.universe, [25, 50, 75]
)

tenure["long"] = fuzz.trimf(
    tenure.universe, [60, 100, 100]
)


# Retention Priority
retention_priority["low"] = fuzz.trimf(
    retention_priority.universe, [0, 0, 40]
)

retention_priority["medium"] = fuzz.trimf(
    retention_priority.universe, [25, 50, 75]
)

retention_priority["high"] = fuzz.trimf(
    retention_priority.universe, [60, 100, 100]
)

# Customer value + churn risk rules

rule1 = ctrl.Rule(
    churn_risk["low"] & customer_value["low"],
    retention_priority["low"]
)

rule2 = ctrl.Rule(
    churn_risk["low"] & customer_value["medium"],
    retention_priority["low"]
)

rule3 = ctrl.Rule(
    churn_risk["low"] & customer_value["high"],
    retention_priority["medium"]
)

rule4 = ctrl.Rule(
    churn_risk["medium"] & customer_value["low"],
    retention_priority["low"]
)

rule5 = ctrl.Rule(
    churn_risk["medium"] & customer_value["medium"],
    retention_priority["medium"]
)

rule6 = ctrl.Rule(
    churn_risk["medium"] & customer_value["high"],
    retention_priority["high"]
)

rule7 = ctrl.Rule(
    churn_risk["high"] & customer_value["low"],
    retention_priority["medium"]
)

rule8 = ctrl.Rule(
    churn_risk["high"] & customer_value["medium"],
    retention_priority["high"]
)

rule9 = ctrl.Rule(
    churn_risk["high"] & customer_value["high"],
    retention_priority["high"]
)


# Tenure-specific rules

rule10 = ctrl.Rule(
    churn_risk["medium"] &
    customer_value["high"] &
    tenure["short"],
    retention_priority["high"]
)

rule11 = ctrl.Rule(
    churn_risk["medium"] &
    customer_value["high"] &
    tenure["long"],
    retention_priority["medium"]
)


# FALLBACK RULES
# These guarantee an output based on churn risk

rule12 = ctrl.Rule(
    churn_risk["low"],
    retention_priority["low"]
)

rule13 = ctrl.Rule(
    churn_risk["medium"],
    retention_priority["medium"]
)

rule14 = ctrl.Rule(
    churn_risk["high"],
    retention_priority["high"]
)

rules = [
    rule1, rule2, rule3,
    rule4, rule5, rule6,
    rule7, rule8, rule9,
    rule10, rule11,
    rule12, rule13, rule14
]

retention_control = ctrl.ControlSystem(rules)

def get_retention_priority(churn, value, tenure):

    # Convert to numbers
    churn = float(churn)
    value = float(value)
    tenure = float(tenure)

    # Handle missing values
    if np.isnan(churn):
        churn = 50

    if np.isnan(value):
        value = 50

    if np.isnan(tenure):
        tenure = 50

    # Keep values between 0 and 100
    churn = np.clip(churn, 0, 100)
    value = np.clip(value, 0, 100)
    tenure = np.clip(tenure, 0, 100)

    # New simulation for each customer
    system = ctrl.ControlSystemSimulation(
        retention_control
    )

    system.input["churn_risk"] = churn
    system.input["customer_value"] = value
    system.input["tenure"] = tenure

    system.compute()

    score = system.output["retention_priority"]

    if score < 40:
        priority = "Low"
    elif score < 70:
        priority = "Medium"
    else:
        priority = "High"

    return score, priority

score, priority = get_retention_priority(
    82,
    85,
    30
)

print("Retention Score:", round(score, 2))
print("Retention Priority:", priority)

tests = [
    (20, 20, 20),
    (50, 50, 50),
    (82, 85, 30),
    (90, 20, 80)
]

for churn, value, tenure in tests:

    score, priority = get_retention_priority(
        churn,
        value,
        tenure
    )

    print(
        "Churn:", churn,
        "| Value:", value,
        "| Tenure:", tenure,
        "| Score:", round(score, 2),
        "| Priority:", priority
    )

