import matplotlib.pyplot as plt
import networkx as nx

# ANN-1 structure
input_features = [
    "Gender", "Age", "State", "City", "Telecom Partner",
    "Dependents", "Estimated Salary", "Calls Made",
    "SMS Sent", "Data Used"
]

input_nodes = len(input_features)
hidden_nodes = 16
output_nodes = 1

G = nx.DiGraph()

# Node positions
pos = {}

# Input layer
for i, feature in enumerate(input_features):
    G.add_node(f"I{i}", layer="Input", label=feature)
    pos[f"I{i}"] = (0, -i)

# Hidden layer
for i in range(hidden_nodes):
    G.add_node(f"H{i}", layer="Hidden", label=f"H{i+1}")
    pos[f"H{i}"] = (2, -(i + 0.5))

# Output layer
G.add_node("O0", layer="Output", label="Churn")
pos["O0"] = (4, -4.5)

# Connections: Input → Hidden
for i in range(input_nodes):
    for j in range(hidden_nodes):
        G.add_edge(f"I{i}", f"H{j}")

# Connections: Hidden → Output
for i in range(hidden_nodes):
    G.add_edge(f"H{i}", "O0")

# Draw
plt.figure(figsize=(14, 9))

nx.draw_networkx_edges(
    G, pos,
    arrows=True,
    arrowsize=8,
    alpha=0.25
)

# Input nodes
nx.draw_networkx_nodes(
    G, pos,
    nodelist=[f"I{i}" for i in range(input_nodes)],
    node_size=500
)

# Hidden nodes
nx.draw_networkx_nodes(
    G, pos,
    nodelist=[f"H{i}" for i in range(hidden_nodes)],
    node_size=350
)

# Output node
nx.draw_networkx_nodes(
    G, pos,
    nodelist=["O0"],
    node_size=900
)

# Input labels
for i, feature in enumerate(input_features):
    x, y = pos[f"I{i}"]
    plt.text(
        x - 0.15, y,
        feature,
        ha="right",
        va="center",
        fontsize=10
    )

# Hidden labels
for i in range(hidden_nodes):
    x, y = pos[f"H{i}"]
    plt.text(
        x, y,
        f"{i+1}",
        ha="center",
        va="center",
        fontsize=8
    )

# Output label
plt.text(
    4, -4.5,
    "Churn\nSigmoid",
    ha="center",
    va="center",
    fontsize=10
)

# Layer titles
plt.text(0, 1, "INPUT LAYER\n10 FEATURES",
         ha="center", fontsize=13, fontweight="bold")

plt.text(2, 3, "HIDDEN LAYER\n16 NEURONS\nReLU",
         ha="center", fontsize=13, fontweight="bold")

plt.text(4, 1, "OUTPUT LAYER\n1 NEURON\nSigmoid",
         ha="center", fontsize=13, fontweight="bold")

plt.title(
    "ANN-1 Network Structure: 10 → 16 → 1",
    fontsize=18,
    fontweight="bold"
)

plt.axis("off")
plt.tight_layout()
plt.show()

import matplotlib.pyplot as plt
import networkx as nx

# ANN-2 structure
input_features = [
    "Gender", "Age", "State", "City", "Telecom Partner",
    "Dependents", "Estimated Salary", "Calls Made",
    "SMS Sent", "Data Used"
]

input_nodes = len(input_features)
hidden1_nodes = 32
hidden2_nodes = 16
output_nodes = 1

G = nx.DiGraph()

# Node positions
pos = {}

# -------------------------
# Input Layer - 10 features
# -------------------------
for i, feature in enumerate(input_features):
    G.add_node(f"I{i}", layer="Input", label=feature)
    pos[f"I{i}"] = (0, -i)

# -------------------------
# Hidden Layer 1 - 32 neurons
# -------------------------
for i in range(hidden1_nodes):
    G.add_node(f"H1_{i}", layer="Hidden1", label=f"{i+1}")

    # Spread 32 neurons vertically
    y = -i * (9 / (hidden1_nodes - 1))
    pos[f"H1_{i}"] = (1, y)

# -------------------------
# Hidden Layer 2 - 16 neurons
# -------------------------
for i in range(hidden2_nodes):
    G.add_node(f"H2_{i}", layer="Hidden2", label=f"{i+1}")

    y = -i * (9 / (hidden2_nodes - 1))
    pos[f"H2_{i}"] = (6, y)

# -------------------------
# Output Layer - 1 neuron
# -------------------------
G.add_node("O0", layer="Output", label="Churn")
pos["O0"] = (9, -4.5)

# -------------------------
# Connections
# -------------------------

# Input → Hidden Layer 1
for i in range(input_nodes):
    for j in range(hidden1_nodes):
        G.add_edge(f"I{i}", f"H1_{j}")

# Hidden Layer 1 → Hidden Layer 2
for i in range(hidden1_nodes):
    for j in range(hidden2_nodes):
        G.add_edge(f"H1_{i}", f"H2_{j}")

# Hidden Layer 2 → Output
for i in range(hidden2_nodes):
    G.add_edge(f"H2_{i}", "O0")

# -------------------------
# Draw network
# -------------------------

plt.figure(figsize=(20, 15))

# Draw connections
nx.draw_networkx_edges(
    G,
    pos,
    arrows=True,
    arrowsize=6,
    alpha=0.15
)

# Input nodes
nx.draw_networkx_nodes(
    G,
    pos,
    nodelist=[f"I{i}" for i in range(input_nodes)],
    node_size=500
)

# Hidden Layer 1 nodes
nx.draw_networkx_nodes(
    G,
    pos,
    nodelist=[f"H1_{i}" for i in range(hidden1_nodes)],
    node_size=180
)

# Hidden Layer 2 nodes
nx.draw_networkx_nodes(
    G,
    pos,
    nodelist=[f"H2_{i}" for i in range(hidden2_nodes)],
    node_size=300
)

# Output node
nx.draw_networkx_nodes(
    G,
    pos,
    nodelist=["O0"],
    node_size=1000
)

# -------------------------
# Input labels
# -------------------------

for i, feature in enumerate(input_features):
    x, y = pos[f"I{i}"]

    plt.text(
        x - 0.15,
        y,
        feature,
        ha="right",
        va="center",
        fontsize=10
    )

# -------------------------
# Hidden Layer 1 labels
# -------------------------

for i in range(hidden1_nodes):
    x, y = pos[f"H1_{i}"]

    plt.text(
        x,
        y,
        f"{i+1}",
        ha="center",
        va="center",
        fontsize=6
    )

# -------------------------
# Hidden Layer 2 labels
# -------------------------

for i in range(hidden2_nodes):
    x, y = pos[f"H2_{i}"]

    plt.text(
        x,
        y,
        f"{i+1}",
        ha="center",
        va="center",
        fontsize=7
    )

# -------------------------
# Output label
# -------------------------

plt.text(
    6,
    -4.5,
    "Churn\nSigmoid",
    ha="center",
    va="center",
    fontsize=10
)

# -------------------------
# Layer titles
# -------------------------

plt.text(
    0,
    2,
    "INPUT LAYER\n10 FEATURES",
    ha="center",
    fontsize=13,
    fontweight="bold"
)

plt.text(
    2,
    2,
    "HIDDEN LAYER 1\n32 NEURONS\nReLU",
    ha="center",
    fontsize=13,
    fontweight="bold"
)

plt.text(
    6,
    2,
    "HIDDEN LAYER 2\n16 NEURONS\nReLU",
    ha="center",
    fontsize=13,
    fontweight="bold"
)

plt.text(
    9,
    2,
    "OUTPUT LAYER\n1 NEURON\nSigmoid",
    ha="center",
    fontsize=13,
    fontweight="bold"
)

# -------------------------
# Title
# -------------------------

plt.title(
    "ANN-2 Network Structure: 10 → 32 → 16 → 1",
    fontsize=18,
    fontweight="bold"
)

plt.axis("off")
